INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ('так', 'Хлібці SunFill з буряком та насінням льону 100г', 'Sunfill', NULL, 'ні', 'Буряк свіжий столовий (41%), насіння льону, насіння ядра соняшника, чорнослив, сіль морська, часник сушений ', NULL, NULL, '4820211260644');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'так', 'Хлібці SunFill з грибами та насінням льону 100г', 'Sunfill', NULL, 'ні', 'Морква свіжа, насіння льону, насіння ядра соняшника, гриби печериці свіжі (13%), цибуля свіжа, сіль морська, кріп сушений ', NULL, NULL, '4820211260613');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'так', 'Хлібці SunFill з овочами та насінням льону 100г', 'Sunfill', NULL, 'ні', 'Овочі свіжі (51.6%) (морква, капуста білокачанна, цибуля), насіння льону, насіння ядра соняшника, сіль морська, часник сушений', NULL, NULL, '4820211260620');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'так', 'Хлібці SunFill зі шпинатом та зеленою гречкою 91г', 'Sunfill', NULL, 'ні', 'Морква свіжа, ядриця зеленої гречки (22%), насіння льону, насіння ядра соняшника, цибуля свіжа, шпинат сухий (1.8%), сіль морська, часник сухий', NULL, NULL, '4820211261566');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ('так', 'Хлібці SunFill з морською капустою та насінням льону 100г', 'Sunfill', NULL, 'ні', 'Морква свіжа, насіння льону, насіння ядра соняшника, сіль морська, капуста морська сушена (1.5%), часник сушений', NULL, NULL, '4820211260606');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'так', 'Хлібці SunFill Дитячі з родзинками та насінням льону 100г', 'Sunfill', NULL, 'ні', 'Морква свіжа, насіння льону, родзинки світлі, насіння ядра соняшнику, кориця мелена', NULL, NULL, '4820211260637');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ('ні', 'Цукерки Bob Snail Яблуко-полуниця у шоколаді 60г', 'Bob Snail', NULL, 'ні', 'Начинка (77%): яблука 61.6%, полуниця 15.4%, молочний шоколад (23%): харчові волокна (олігофруктоза), какао-масло, сухе незбиране молоко, сухе знежирене молоко, какао-маса, емульгатор: соняшниковий лецитин, натуральний ароматизатор ваніль, підсолоджувач: екстракт стевії ', NULL, NULL, '4820219341369');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ('ні', 'Цукерки Bob Snail Choco яблучно-малинові у чорному шоколаді 60г', 'Bob Snail', NULL, 'ні', 'Начинка (77%): яблука 61.6%, малина 15.4%, чорний шоколад (23%): какао терте, харчові волокна (олігофруктоза), какао-порошок з пониженим вмістом жиру, молочний жир, соняшниковий лецитин, натуральний ароматизатор ваніль, екстракт стевії', NULL, NULL, '4820219341345');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'ні', 'Цукерки Bob Snail Choco яблучно-вишневі у чорному шоколаді 60г', 'Bob Snail', NULL, 'ні', 'Начинка (77%): яблука 61.6%, вишні 15.4%, чорний шоколад (23%): какао терте, харчові волокна (олігофруктоза), какао-порошок з пониженим вмістом жиру, молочний жир, соняшниковий лецитин, натуральний ароматизатор ваніль, екстракт стевії ', NULL, NULL, '4820219341338');
INSERT INTO products (is_vegan, name, brand, certification, project_check, ingredients, photo, additional, barcode) VALUES ( 'ні', 'Цукерки Sunfill Марципан 150г', 'ні', NULL, 'ні', 'Мигдальний горіх, мед', NULL, NULL, '4820211260255');
